\set ON_ERROR_STOP on
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
do $test$ declare oid uuid;unpaid uuid;cancelled uuid;r uuid;r2 uuid;op uuid;item uuid;payload jsonb;selection jsonb;rev integer;out jsonb;before_count integer;cash bigint;stock integer;before_stock integer;return_key uuid;begin
 perform public.save_deal('17171717-0000-4000-8000-000000000101',(select revision from app_private.deal_settings where deal_id='17171717-0000-4000-8000-000000000101'),gen_random_uuid(),'save','{"title":"Synthetic reporting deal","slug":"synthetic-race-deal-1","priceMinor":100001,"components":[{"id":"15151515-0000-4000-8000-000000000002","quantity":3}]}');
 before_count=(select count(*) from app_private.completed_sales);oid=report_test.place(4,true);unpaid=report_test.place();
 perform report_test.ok((select count(*) from app_private.completed_sales)=before_count,'placement is not a sale');
 perform report_test.pay(oid);perform report_test.ok((select count(*) from app_private.completed_sales)=before_count,'verified receipts are not sales');
 perform report_test.step(oid,'confirm');perform report_test.step(oid,'dispatch');perform report_test.ok((select count(*) from app_private.completed_sales)=before_count,'dispatch is not a sale');
 stock=(select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002');op=gen_random_uuid();rev=(select revision from app_private.commerce_orders where order_id=oid);
 perform public.admin_order_action(oid,rev,'complete',op);perform public.admin_order_action(oid,rev,'complete',op);
 perform public.review_manual_payment(oid,(select revision from app_private.commerce_orders where order_id=oid),'verify',gen_random_uuid(),jsonb_build_object('checkedHistory',true,'amountMinor',20000,'reference','SYNTHETIC-EXTRA-'||oid,'reacquire',false));
 perform report_test.ok((select count(*) from app_private.completed_sales)=before_count+1,'completion/retry records one sale');
 perform report_test.ok((select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002')=stock,'completion does not deduct stock');
 perform report_test.ok((select merchandise_minor=600002 and shipping_minor=12345 from app_private.completed_sales where order_id=oid),'historical deal charged revenue counted once');
 perform report_test.ok((select sum(attributed_minor)=600002 from app_private.finance_components(oid)),'component attribution equals charged merchandise exactly');
 selection=report_test.selection(oid,true,1,12345,20000);r=report_test.request(oid,selection);
 perform report_test.ok((public.admin_order_finance(oid)->>'reservedMinor')::bigint=0,'request does not reserve money');
 perform report_test.finance(oid,'approve',jsonb_build_object('refundId',r,'reason','Synthetic approval'));
 perform report_test.ok((public.admin_order_finance(oid)->>'reservedMinor')::bigint=65678,'approval reserves partial component/shipping/overpayment exact paisa');
 perform report_test.denied(format('select report_test.finance(%L::uuid,''send'',%L::jsonb)',oid,jsonb_build_object('refundId',r,'reason','Not confirmed','method','bank-transfer','account','Synthetic','reference','not-verified','sentAt',clock_timestamp())),'no send without explicit outgoing-history check');
 op=gen_random_uuid();rev=(public.admin_order_finance(oid)->>'revision')::integer;payload=jsonb_build_object('refundId',r,'reason','Synthetic verified transfer','method','bank-transfer','account','Synthetic account','reference','SYNTHETIC-UNIQUE-REF','sentAt',clock_timestamp(),'checkedHistory',true,'amountMinor',1);
 perform public.admin_finance_action(oid,rev,op,'send',payload);perform public.admin_finance_action(oid,rev,op,'send',payload);
 perform report_test.ok((select count(*)=1 from app_private.refund_events where refund_id=r and action='send'),'send retry has one immutable transfer');
 perform report_test.ok((select amount_minor=65678 from app_private.refund_requests where id=r),'browser amount cannot override refund allocation');
 perform report_test.ok((select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002')=stock,'refund without return does not restock');
 perform report_test.denied(format('select report_test.request(%L::uuid,%L::jsonb)',oid,report_test.selection(oid,true,6)),'cannot refund previously held/sent item quantity again');
 r2=report_test.request(oid,report_test.selection(oid,true,5));perform report_test.finance(oid,'approve',jsonb_build_object('refundId',r2,'reason','Synthetic remaining component approval'));
 perform report_test.ok((select amount_minor=166669 from app_private.refund_requests where id=r2),'remaining component refund receives exact rounding remainder');
 perform report_test.denied(format('select report_test.send(%L::uuid,%L::uuid,''SYNTHETIC-UNIQUE-REF'')',oid,r2),'reused outgoing reference blocked');
 perform report_test.finance(oid,'cancel',jsonb_build_object('refundId',r2,'reason','Synthetic cancellation'));
 perform report_test.ok((public.admin_order_finance(oid)->>'reservedMinor')::bigint=0,'cancel unsent restores refundable balance');
 item=(select id from public.order_items where order_id=oid and deal_id is not null);return_key=gen_random_uuid();payload=jsonb_build_object('itemId',item,'variantId','15151515-0000-4000-8000-000000000002','quantity',2,'resaleQuantity',1,'receivedAt',clock_timestamp(),'inspected',true,'reason','One resale, one damaged synthetic return');rev=(public.admin_order_finance(oid)->>'revision')::integer;
 perform public.admin_finance_action(oid,rev,return_key,'return',payload);perform public.admin_finance_action(oid,rev,return_key,'return',payload);
 perform report_test.ok((select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002')=stock+1,'partial deal return restocks resale only, retry once');
 perform report_test.denied(format('select report_test.finance(%L::uuid,''return'',%L::jsonb)',oid,payload||'{"quantity":5}'),'return cannot exceed dispatched less already returned');
 perform report_test.finance(oid,'reverse-return',jsonb_build_object('returnId',return_key,'reason','Synthetic return entry correction','inspected',true));
 perform report_test.ok((select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002')=stock,'return correction audited without duplicate stock');
 perform report_test.denied(format('select report_test.finance(%L::uuid,''reverse-return'',%L::jsonb)',oid,jsonb_build_object('returnId',return_key,'reason','Second reversal','inspected',true)),'duplicate return reversal blocked');
 cancelled=report_test.place();perform report_test.pay(cancelled);before_stock=(select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002');perform report_test.step(cancelled,'cancel');
 perform report_test.ok((select on_hand from public.inventory_balances where variant_id='15151515-0000-4000-8000-000000000002')=before_stock,'pre-dispatch cancel releases, never adds physical stock');
 r2=report_test.request(cancelled,report_test.selection(cancelled,false,1,12345));perform report_test.finance(cancelled,'approve',jsonb_build_object('refundId',r2,'reason','Synthetic cancelled refund'));perform report_test.send(cancelled,r2);
 perform report_test.ok((select not sales_applicable and merchandise_minor=100000 from app_private.refund_events where refund_id=r2 and action='send'),'uncompleted/cancelled refund is cash-only');
 perform report_test.ok((select sum(merchandise_minor)=-33333 from app_private.reporting_events() where event='refund sent' and order_id in(oid,cancelled)),'only eligible completed merchandise refund reduces sales');
 perform report_test.ok((select sum(refunds_minor)=178023 from app_private.reporting_events() where order_id in(oid,cancelled)),'cash includes full cancelled, shipping and overpayment refunds');
 perform report_test.finance(oid,'reverse',jsonb_build_object('refundId',r,'reason','Synthetic mistaken refund correction','checkedHistory',true));
 perform report_test.ok((select count(*)=2 from app_private.refund_events where refund_id=r and action in('send','reverse')),'refund correction appends reversal, never deletes history');
 perform report_test.ok((select sum(merchandise_minor)=0 from app_private.reporting_events() where event in('refund sent','refund record reversal') and order_id=oid),'reversal restores ledger with a new dated event');
 perform report_test.denied(format('select report_test.finance(%L::uuid,''return'',%L::jsonb)',cancelled,jsonb_build_object('itemId',(select id from public.order_items where order_id=cancelled),'variantId','15151515-0000-4000-8000-000000000002','quantity',1,'resaleQuantity',1,'receivedAt',clock_timestamp(),'reason','Synthetic invalid pre-dispatch return','inspected',true)),'cancelled undispatched return rejected');
 perform report_test.denied(format('update app_private.refund_events set amount_minor=1 where refund_id=%L::uuid',r),'financial events immutable');
 perform report_test.ok((select start_at='2026-01-31 19:00:00+00'::timestamptz and end_at='2026-02-01 19:00:00+00'::timestamptz from public.karachi_day_bounds('2026-02-01')),'Pakistan day/month boundaries convert to UTC correctly');
 perform report_test.ok((public.admin_sales_report()->'totals'->>'completedOrders')::integer=0,'development orders isolated from business reports');
 out=public.admin_sales_report(null,null,'month',0,25,false,true,true);
 perform report_test.ok((out->>'totalEvents')::integer=jsonb_array_length(out->'events'),'export includes all filtered events');
 perform report_test.ok((out->'totals'->>'grossMerchandiseMinor')::bigint=(select sum(merchandise_minor) from app_private.completed_sales),'report gross equals historical completed ledger');
 perform report_test.ok((out->'totals'->>'refundsSentMinor')::bigint=(select sum(refunds_minor) from app_private.reporting_events()),'CSV source/report cash totals agree');
 perform report_test.ok(jsonb_array_length(public.admin_sales_report('2099-01-01','2099-01-02','day',p_development=>true)->'events')=0,'empty future range excludes actual events');
 perform report_test.denied('select public.admin_sales_report(null,null,''day'',null,null,false,false)','null pagination cannot remove bounds');
 perform report_test.step(unpaid,'cancel');
end $test$;
set role anon;
do $$ begin begin perform public.admin_sales_report();raise exception 'Anonymous report passed';exception when others then if sqlerrm='Anonymous report passed' then raise;end if;end;end $$;
reset role;
set role authenticated;set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
-- Authenticated has execute but cannot self-assign admin or read private finance.
do $$ begin begin perform public.admin_sales_report();raise exception 'Unauthorized report passed';exception when others then if sqlerrm='Unauthorized report passed' then raise;end if;end;end $$;
reset role;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select report_test.ok(not exists(select 1 from pg_policies where schemaname='app_private' and tablename in('completed_sales','receipt_dates','finance_versions','refund_requests','refund_events','return_events','finance_operations')),'private finance has no client policies');
